async function run() {
  const tickersParam = (params.tickers || "PETR4,ITUB4,MXRF11");
  const tickers = tickersParam.split(",").map(t => t.trim().toUpperCase()).filter(Boolean);
  if (tickers.length === 0) {
    log("Nenhum ticker configurado");
    return;
  }

  const url = "https://brapi.dev/api/quote/" + tickers.join(",");
  const data = await http.getJSON(url);
  const results = (data && data.results) || [];

  const threshold = (params.threshold !== undefined && params.threshold !== null) ? params.threshold : 2;

  const lines = [];
  for (const t of tickers) {
    const r = results.find(x => x.symbol === t);
    if (!r) continue;
    const price = money.format(r.regularMarketPrice, "BRL");
    const pct = r.regularMarketChangePercent;
    const sign = pct > 0 ? "+" : "";
    const pctText = sign + pct.toFixed(1).replace(".", ",") + "%";
    const warn = Math.abs(pct) > threshold ? "⚠️ " : "";
    lines.push(warn + t + " " + price + " (" + pctText + ")");
  }

  if (lines.length === 0) {
    log("Nenhuma cotação encontrada para os tickers configurados");
    return;
  }

  const text = "📈 Cotações:\n" + lines.join("\n");
  await notify.send({ text });
}
